def extend_shader19114(text):
    for old,new in DELTA:
        if text.count(old)!=1:raise AssertionError('Strong .114 forward anchor mismatch')
        text=text.replace(old,new,1)
    return text

def restore_shader19114(text,required=False):
    if 'GX_GUIDE_REUSE19114' not in text:
        if required:raise AssertionError('Strong .114 delta absent')
        return text
    for old,new in DELTA:
        if text.count(new)!=1:raise AssertionError('Strong .114 inverse anchor mismatch')
        text=text.replace(new,old,1)
    if '19114' in text:raise AssertionError('Unreviewed Strong .114 delta remains')
    return text
